def validate_order(body):
    errors = []
    if 'quantity' not in body:
        errors.append('quantity: required')
    else:
        q = body['quantity']
        if isinstance(q, bool) or not isinstance(q, int):
            errors.append('quantity: must be integer')
        elif not 1 <= q <= 99:
            errors.append('quantity: out of range')
    if 'sku' not in body:
        errors.append('sku: required')
    elif not isinstance(body['sku'], str) or not body['sku'].strip():
        errors.append('sku: must be non-empty string')
    return sorted(errors)
